706	    private SetBuilderImpl<E> insertInHashTable(E e) {
707	      requireNonNull(hashTable);
708	      int eHash = e.hashCode();
709	      int i0 = Hashing.smear(eHash);
710	      int mask = hashTable.length - 1;
711	      for (int i = i0; i - i0 < maxRunBeforeFallback; i++) {
712	        int index = i & mask;
713	        Object tableEntry = hashTable[index];
714	        if (tableEntry == null) {
715	          addDedupedElement(e);
716	          hashTable[index] = e;
717	          hashCode += eHash;
718	          ensureTableCapacity(distinct); // rebuilds table if necessary
719	          return this;
720	        } else if (tableEntry.equals(e)) { // not a new element, ignore
721	          return this;
722	        }
723	      }
724	      // we fell out of the loop due to a long run; fall back to JDK impl
725	      return new JdkBackedSetBuilderImpl<E>(this).add(e);
