773	    /** Builds a new open-addressed hash table from the first n objects in elements. */
774	    static @Nullable Object[] rebuildHashTable(int newTableSize, Object[] elements, int n) {
775	      @Nullable Object[] hashTable = new @Nullable Object[newTableSize];
776	      int mask = hashTable.length - 1;
777	      for (int i = 0; i < n; i++) {
778	        // requireNonNull is safe because we ensure that the first n elements have been populated.
779	        Object e = requireNonNull(elements[i]);
780	        int j0 = Hashing.smear(e.hashCode());
781	        for (int j = j0; ; j++) {
782	          int index = j & mask;
783	          if (hashTable[index] == null) {
784	            hashTable[index] = e;
785	            break;
786	          }
787	        }
788	      }
789	      return hashTable;
