792	    void ensureTableCapacity(int minCapacity) {
793	      int newTableSize;
794	      if (hashTable == null) {
795	        newTableSize = chooseTableSize(minCapacity);
796	        hashTable = new Object[newTableSize];
797	      } else if (minCapacity > expandTableThreshold && hashTable.length < MAX_TABLE_SIZE) {
798	        newTableSize = hashTable.length * 2;
799	        hashTable = rebuildHashTable(newTableSize, dedupedElements, distinct);
800	      } else {
801	        return;
802	      }
803	      maxRunBeforeFallback = maxRunBeforeFallback(newTableSize);
804	      expandTableThreshold = (int) (DESIRED_LOAD_FACTOR * newTableSize);
805	    }
