807	    /**
808	     * We attempt to detect deliberate hash flooding attempts. If one is detected, we fall back to a
809	     * wrapper around j.u.HashSet, which has built-in flooding protection. MAX_RUN_MULTIPLIER was
810	     * determined experimentally to match our desired probability of false positives.
811	     */
812	    // NB: yes, this is surprisingly high, but that's what the experiments said was necessary
813	    // Raising this number slows the worst-case contains behavior, speeds up hashFloodingDetected,
814	    // and reduces the false-positive probability.
815	    static final int MAX_RUN_MULTIPLIER = 13;
816	
817	    /**
818	     * Checks the whole hash table for poor hash distribution. Takes O(n) in the worst case, O(n /
819	     * log n) on average.
820	     *
821	     * <p>The online hash flooding detecting in RegularSetBuilderImpl.add can detect e.g. many
822	     * exactly matching hash codes, which would cause construction to take O(n^2), but can't detect
823	     * e.g. hash codes adversarially designed to go into ascending table locations, which keeps
824	     * construction O(n) (as desired) but then can have O(n) queries later.
825	     *
826	     * <p>If this returns false, then no query can take more than O(log n).
827	     *
828	     * <p>Note that for a RegularImmutableSet with elements with truly random hash codes, contains
829	     * operations take expected O(1) time but with high probability take O(log n) for at least some
830	     * element. (https://en.wikipedia.org/wiki/Linear_probing#Analysis)
831	     *
832	     * <p>This method may return {@code true} even on truly random input, but {@code
833	     * ImmutableSetTest} tests that the probability of that is low.
834	     */
835	    static boolean hashFloodingDetected(@Nullable Object[] hashTable) {
836	      int maxRunBeforeFallback = maxRunBeforeFallback(hashTable.length);
837	      int mask = hashTable.length - 1;
838	
839	      // Invariant: all elements at indices in [knownRunStart, knownRunEnd) are nonnull.
840	      // If knownRunStart == knownRunEnd, this is vacuously true.
841	      // When knownRunEnd exceeds hashTable.length, it "wraps", detecting runs around the end
842	      // of the table.
843	      int knownRunStart = 0;
844	      int knownRunEnd = 0;
845	
846	      outerLoop:
847	      while (knownRunStart < hashTable.length) {
848	        if (knownRunStart == knownRunEnd && hashTable[knownRunStart] == null) {
849	          if (hashTable[(knownRunStart + maxRunBeforeFallback - 1) & mask] == null) {
850	            // There are only maxRunBeforeFallback - 1 elements between here and there,
851	            // so even if they were all nonnull, we wouldn't detect a hash flood.  Therefore,
852	            // we can skip them all.
853	            knownRunStart += maxRunBeforeFallback;
854	          } else {
855	            knownRunStart++; // the only case in which maxRunEnd doesn't increase by mRBF
856	            // happens about f * (1-f) for f = DESIRED_LOAD_FACTOR, so around 21% of the time
857	          }
858	          knownRunEnd = knownRunStart;
859	        } else {
860	          for (int j = knownRunStart + maxRunBeforeFallback - 1; j >= knownRunEnd; j--) {
861	            if (hashTable[j & mask] == null) {
862	              knownRunEnd = knownRunStart + maxRunBeforeFallback;
863	              knownRunStart = j + 1;
864	              continue outerLoop;
865	            }
866	          }
867	          return true;
868	        }
869	      }
870	      return false;
871	    }
