873	    /**
874	     * If more than this many consecutive positions are filled in a table of the specified size,
875	     * report probable hash flooding. ({@link #hashFloodingDetected} may also report hash flooding
876	     * if fewer consecutive positions are filled; see that method for details.)
877	     */
878	    static int maxRunBeforeFallback(int tableSize) {
879	      return MAX_RUN_MULTIPLIER * IntMath.log2(tableSize, RoundingMode.UNNECESSARY);
880	    }
